// === Tab: mySketch ===
const strokeCol = "#121212";
const fillCol = "#F2F0E9";

let duration = 300;
let time = 0;

let hairLevel = [];
let hairRandomPos = [];

function setup() {
	createCanvas(700, 700);

	strokeJoin(ROUND);
	noiseDetail(6, 0.25);
	rectMode(CORNERS);

	initHair();
}

function draw() {
	background(fillCol);

	face();

	if(frameCount % 240 ==0){
		initHair();
	}
}

function face() {
	time++;
	strokeWeight(30);
	noFill();
	stroke(strokeCol);
	fill(fillCol);
	circle(width * 0.17, height * 0.55 - 10, width * 0.25);
	circle(width * 0.83, height * 0.55 - 10, width * 0.25);
	circle(width / 2, height * 0.55, width * 0.7);

	eyebrow(width * 0.35, height * 0.5, width * 0.12, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) ? (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) : 0, 0, width, -PI / 12, PI / 12), -0.2);
	eyebrow(width * 0.65, height * 0.5, width * 0.12, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) ? (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) : 0, 0, width, PI / 12, -PI / 12), 0.2);
	eye(width * 0.35, height * 0.6, width * 0.07);
	eye(width * 0.65, height * 0.6, width * 0.07);


	nose(width/2,height*0.6,10);
	mouth(width / 2, height * 0.75, 100, 20, 0.1, frameCount * 0.1, frameCount * 0.01, 50, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) ? (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) : 0, 0, height, -1, 1));

	fill(strokeCol);
	hair(width/2,height*0.53,width*0.36,PI/10,height*0.4,50);
}

function eyebrow(x, y, length, angle, shift = 0) {
	push();
	translate(x, y);
	rotate(angle);
	line(length / 2 + length / 2 * shift, 0, -length / 2 + length / 2 * shift, 0);
	pop();
}

function eye(x, y, length) {
	let f = 1;
	if (time) {
		if (time < 10) {
			f = easeInOutSine(map(time, 0, 10, 1, 0));
		} else if (time < 20) {
			f = easeInOutSine(map(time, 10, 20, 0, 1));
		}
	}
	if (time >= duration) {
		time = 0;
		duration = floor(random() < 0.2 ? 20 : random(random(120, 600)));
	}
	rect(x - length / 2 * (1 - f), y - length / 2 * easeInOutSine(f), x + length / 2 * (1 - f), y + length / 2 * easeInOutSine(f));
}

function mouth(x, y, length, level, scale, t, w, subdivision, f) {
	f = constrain(f, -1, 1);
	beginShape();
	for (let i = 0; i < subdivision; i++) {
		let n = level * (noise(i * scale + t, w) * 2 - 1);
		let defp1 = createVector(x + length * cos(map(i, 0, subdivision, PI, 0)) / 2, y - length*0.2 + length * sin(map(i, 0, subdivision, PI, 0)) / 2);
		let defp2 = createVector(x + map(i, 0, subdivision, -length * 0.7, length * 0.7), y + n);
		let defp3 = createVector(x + length * cos(map(i, 0, subdivision, -PI, 0)) / 2, y + length*0.2 + length * sin(map(i, 0, subdivision, -PI, 0)) / 2);

		let p = f < 0 ? p5.Vector.lerp(defp1, defp2, f + 1) : p5.Vector.lerp(defp2, defp3, f);
		vertex(p.x, p.y);
	}
	endShape();

}

function nose(x,y,d){
	circle(x,y,d);
}

function beret() {

	arcByPoint();
}

function hair(x,y,r,angle,height,scale){
	beginShape();
	for(let i=0;i<=15;i++){
		let theta = map(i,0,15,-angle,angle-PI);
		vertex(x+r*cos(theta)*hairRandomPos[i],y+r*sin(theta)*hairRandomPos[i]);
	}
	for(let i=0;i<=hairLevel.length;i++){
		if(i>0&&i<hairLevel.length){
			vertex(map(i,0,hairLevel.length,x+r*cos(angle-PI),x+r*cos(-angle)),scale*hairLevel[i-1]+height);
		}
	}
	endShape(CLOSE);
}

function arcByPoint(p1, p2, p3) {
	// 3点が一直線上にある場合は円を作れない
	let d = 2 * p5.Vector.sub(p2, p1).cross(p5.Vector.sub(p3, p1));

	if (abs(d) < 0.001) {
		line(p1.x, p1.y, p2.x, p2.y);
		return null;
	}

	// 円の中心座標を計算
	let u = createVector(
		(p1.magSq() * (p2.y - p3.y) + p2.magSq() * (p3.y - p1.y) + p3.magSq() * (p1.y - p2.y)) / d,
		(p1.magSq() * (p3.x - p2.x) + p2.magSq() * (p1.x - p3.x) + p3.magSq() * (p2.x - p1.x)) / d
	);

	// 半径を計算
	let r = u.dist(p1);

	let up1 = p5.Vector.sub(p1, u);
	let up2 = p5.Vector.sub(p2, u);

	arc(u.x, u.y, r, r, up1.heading(), up2.heading());
}

function easeInOutSine(x) {
	return -(Math.cos(Math.PI * x) - 1) / 2;
}

function initHair(){
	hairLevel = [];
	hairRandomPos = [];

	for(let i=0;i<15;i++){
		hairLevel.push(random(-1,1));
		hairRandomPos.push(random(1,1.3));
	}
	hairRandomPos.push(random(1,1.3));
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
